import click
from click.shell_completion import CompletionItem, shell_complete

class Foo(click.ParamType):
    def convert(self, value, param, ctx):
        return value

    def shell_complete(self, ctx, param, incomplete):
        return [
            CompletionItem(value=value, help="adsf") for value in 
            ["baz:quux", "spam:eggs"]
        ]

@click.command()
@click.argument("foo", type=Foo())
def main(foo):
    print(foo)


def test_shell_completion():
    cli = click.Command('foo', params=[click.Argument(['foo'], type=Foo())])
    ctx_args = {}
    prog_name = 'foo'
    complete_var = '_FOO_COMPLETE'
    instruction = 'complete'
    exit_code = shell_complete(cli, ctx_args, prog_name, complete_var, instruction)
    assert exit_code == 0
