import pytest
import click


def _get_completions(cli, args, incomplete):
    from click.shell_completion import ShellComplete
    comp = ShellComplete(cli, {}, cli.name, "_CLICK_COMPLETE")
    return comp.get_completions(args, incomplete)


def test_multiline_help_option():
    @click.command()
    @click.option(
        "--at",
        type=(str, str),
        multiple=True,
        help="\b\nAttachment with explicit mimetype,\n--at image.jpg image/jpeg"
    )
    def cli(at):
        pass

    # Simulate the command line input for completion
    completions = _get_completions(cli, ["--"], "")
    assert completions is not None
    assert any(c.value.startswith('--at') for c in completions), "Expected '--at' to be in completions"

    # Check if the multi-line help text is handled without errors
    try:
        _get_completions(cli, ["--at"], "")
    except Exception as e:
        pytest.fail(f"Completion raised an exception: {e}")

import pytest
import click

class MyClass:
    @staticmethod
    def from_str(input: str) -> 'MyClass':
        if input != 'works':
            raise ValueError(f'input was {input=}, should be works')
        return MyClass()

@pytest.mark.parametrize('input_value', [
    'fail',
])
def test_func_param_type(input_value):
    param_type = click.types.FuncParamType(MyClass.from_str)
    with pytest.raises(click.exceptions.BadParameter) as excinfo:
        param_type.convert(input_value, None, None)
    assert str(excinfo.value) == input_value

import pytest
from jinja2 import Environment, Template


def test_groupby_case_sensitive():
    env = Environment()
    template = Template("""
    {% set items = ['apple', 'Apple', 'banana', 'Banana'] %}
    {% set grouped = items | groupby('lower') %}
    {% for key, group in grouped %}
        {{ key }}: {{ group | join(', ') }}
    {% endfor %}
    """)
    output = template.render(environment=env)
    expected_output = 'apple: apple, Apple\nbanana: banana, Banana\n'
    assert output == expected_output


def test_groupby_case_insensitive():
    env = Environment()
    template = Template("""
    {% set items = ['apple', 'Apple', 'banana', 'Banana'] %}
    {% set grouped = items | groupby('lower', case_sensitive=False) %}
    {% for key, group in grouped %}
        {{ key }}: {{ group | join(', ') }}
    {% endfor %}
    """)
    output = template.render(environment=env)
    expected_output = 'apple: apple, Apple\nbanana: banana, Banana\n'
    assert output == expected_output

