import pytest
import jinja2

@pytest.fixture
def jinja_env():
    env = jinja2.Environment(enable_async=True)
    env.filters['add_two'] = lambda x, y: [i + y for i in x]
    return env

def test_add_two_filter_with_async(jinja_env):
    template = '{% for item in (a.b | add_two(5))[:1] %}{{ item }}{% endfor %}'
    a = {'b': [1, 2, 3]}
    with pytest.raises(TypeError, match="'coroutine' object is not subscriptable"):
        jinja_env.from_string(template).render(a=a)

import pytest
from rich.console import Console
from rich.prompt import Confirm

class MockConsole:
    def __init__(self, markup):
        self.markup = markup
        self.output = ''

    def print(self, message):
        if self.markup:
            self.output += f'<markup>{message}</markup>'
        else:
            self.output += str(message)

    def input(self, prompt, password=False, stream=None):
        # Simulate invalid input
        return 'invalid_input'

@pytest.fixture
def console():
    return MockConsole(markup=False)

def test_confirm_invalid_response(console):
    # Simulate an invalid response
    with pytest.raises(SystemExit):
        Confirm.ask("Choose Y or N:", console=console)
    assert '[prompt.invalid]Please enter Y or N' in console.output

import unittest

from sqlglot import parse_one, ParseError

